-- migrate:up
-- PULSE-HQ (owner, 23 Oct 2026): the founder's ideas of 23 Oct on the Pulse HQ ideas board, Stack Intelligence in the
-- feature catalogue, and Stack Intelligence's first research (69 tools, services, infrastructure and AI models with
-- cost, free tier and limits, pros and cons, a verdict and sources checked 23 Oct 2026) with four stacks from the
-- research's budget scenarios (₹0 free tier, creative ₹0–1k, ₹3–5k, ₹15–20k). Tools are upserted by name; ideas and
-- stacks are added once (by title or name). Plain SQL over tables defined in this repository's migrations (0944, 0973).
-- Only in the Pulse organisation (@pulsehq); where it does not exist nothing happens. Safe on a live install.
do $$
declare v_org uuid; v_person uuid; v_feature uuid;
begin
  select id into v_org from pulse.org where handle = 'pulsehq';
  if v_org is null then return; end if;
  perform set_config('pulse.org_id', v_org::text, true);
  select m.person_id into v_person from pulse_priv.account_member m join pulse_priv.pulse_account a on a.id = m.account_id
   where a.handle = 'savuzo' and m.member_org = v_org;

  -- Stack Intelligence joins the catalogue (a draft until the founder reviews it).
  insert into pulse.hq_feature(org_id, key, category, name, promise, what, who, status, icon, proof, sort, draft, href, created_by)
  values (v_org, 'stack-intelligence', 'platform', 'Stack Intelligence', 'Choose tools, services and AI models with costs, verdicts and benchmarks side by side',
    'One place for the tools a company weighs (compute, CI, monitoring, LLM observability, device testing, video and voice, AI models and routers, storage): plan, monthly cost in USD and INR, free tier and limits, pros and cons, a tech-radar verdict (adopt, trial, assess, hold), status, owner, sources with the date checked and benchmarks. Views: sheet, board, radar, comparison of 2–5 tools and a budget with three scenarios. Named stacks can be shared by link or published to the Pulse stack directory, where any organisation can copy one. AI employees read it to recommend tools.',
    'Founders, IT & developers', 'beta', 'Radar', '/stack, stack-intel.ts, 0973_stack_intelligence.sql', 40, true, '/stack', v_person)
  on conflict (org_id, key) do nothing;
  select id into v_feature from pulse.hq_feature where org_id = v_org and key = 'stack-intelligence';

  -- The ideas already on the board keep the order they were shown in (newest first), after the new ones.
  update pulse.hq_idea i set sort = x.n from (select id, (row_number() over (order by created_at desc))::int - 1 n from pulse.hq_idea where org_id = v_org) x
   where x.id = i.id and i.sort = 0;

  insert into pulse.hq_idea(org_id, title, problem, for_whom, details, impact, effort, status, area, feature_keys, feature_id, owner_id, sort, created_by)
  select v_org, x.title, x.problem, x.for_whom, x.details, x.impact, x.effort, x.status, x.area, x.keys, case when x.title = 'Stack Intelligence with shareable stacks' then v_feature end,
    v_person, -100 + x.n, v_person
  from (values
    ('Product Story module', 'Nobody can see how a product grew: what shipped in which version, how it looked then and what changed. Release notes, screenshots, tutorials, tests and deploys sit in different places, so onboarding, sales demos and investor updates are rebuilt by hand every time.',
     'Founders, product teams and their clients',
     'A version timeline from the first idea to now. Each version has its tutorials, screens and changelog. Compare two versions side by side (screens, flows, features). An engineering view per version: releases, tests run, bugs found and fixed, deploys. Links to the feature catalogue (what each version added) and to the Reels pipeline (a tutorial per version).',
     4, 4, 'new', 'work', array['updates-feed', 'outcomes', 'projects']::text[], 0),
    ('Reels-first tutorial pipeline', 'Tutorials take hours to record and edit, go stale with every release and are not made for phones, where people actually watch.',
     'Founders and marketing, and every customer learning Pulse',
     'Remotion renders from logged UI actions: frame-accurate cuts on each logged action, 9:16 first, word-by-word captions, an ElevenLabs v3 voice with sound effects and music ducked under speech, and an automatic QA pass (caption timing, black frames, loudness, cut points) before anyone reviews it. One tutorial per feature and per version (Product Story).',
     4, 4, 'new', 'creative', array['media-review', 'asset-tracker', 'install-guides']::text[], 1),
    ('Two-phone mobile testing harness', 'Phone bugs surface late because calls, chat and notifications need two real phones at once and nobody records what happened.',
     'The Pulse engineering team (and AI employees testing builds)',
     'Two Android phones on the dev box: Maestro flows drive both (one calls, one answers; one sends, one receives), scrcpy records each screen, and every failure writes a defects.md entry with the clip, the step and the build. The loop: run, read defects.md, fix, run again.',
     4, 3, 'new', 'apps', array['phone-app', 'calls', 'push-notifications']::text[], 2),
    ('Stack Intelligence with shareable stacks', 'Choosing tools, services, infrastructure and AI models is guesswork: costs, free-tier limits and verdicts live in chats and browser tabs, and every company repeats the same research.',
     'Founders and IT leads choosing tools, and any organisation on Pulse',
     'Built 23 Oct 2026 in Pulse HQ (/stack): tools with category, plan, monthly cost in USD and INR, free tier and limits, pros, cons, best for, a radar verdict (adopt, trial, assess, hold), status, owner, sources and benchmarks. Views: sheet, board, radar, comparison of 2–5 tools, budget with three scenarios. Named stacks shared by link or published to the Pulse stack directory; others copy one with "Use this stack". AI employees read it to recommend tools.',
     4, 3, 'building', 'platform', array['stack-intelligence', 'self-hosted', 'connect-ai']::text[], 3),
    ('Decision routing via OpenRouter', 'Every Pip intent and AI-employee step goes to the same expensive model, so simple decisions cost as much as hard ones and quota runs out.',
     'Pip and every AI employee; organisations paying for AI',
     'A cheap first hop for Pip''s intent engine and AI employees through OpenRouter: the Jev router and the "decisions" models (Decider Flash) classify and decide; low confidence or a hard task escalates to the Claude subscription. Free models only for public data. Cost and confidence logged per decision (Langfuse).',
     5, 3, 'new', 'chats', array['pip-assistant', 'ai-employees', 'connect-ai', 'ai-api-keys']::text[], 4),
    ('Sentry error and session replay across web, API and mobile', 'Errors are found when a person complains; there is no trace of what they did before it broke on the web, in the API or on the phone.',
     'The Pulse engineering team, and support answering customers',
     'Sentry (Developer tier first) on the web app, the API and the Android app: errors with releases and source maps, performance traces, and session replay with personal data masked. Alerts into the engineering chat. PostHog alongside for product analytics.',
     4, 2, 'new', 'platform', array['phone-app', 'desktop-app', 'api-v1']::text[], 5),
    ('Langfuse tracing for AI employees', 'When an AI employee answers badly or spends too much, nobody can see the prompt, the tools it called or what it cost.',
     'Owners running AI employees, and the Pulse team improving them',
     'Every AI-employee run traced in Langfuse (Hobby to start, self-host later): prompt, model, tools, tokens, cost, latency and the person''s approval or edit as a score. Evals on saved runs before changing a prompt or model.',
     4, 2, 'new', 'chats', array['ai-employees', 'agent-workspaces', 'ai-ask-first']::text[], 6),
    ('Self-hosted CI runners on free or cheap ARM', 'Builds, tests and agents run on the production box, burn its CPU credits and get throttled to 30%, so CI and production both slow down.',
     'The Pulse engineering team and the AI employees building Pulse',
     'GitHub self-hosted runners on Oracle Cloud Always Free (Ampere A1, 2 OCPU / 12 GB), Blacksmith''s free minutes for heavy Docker jobs, and a dedicated-core box (Netcup RS 1000) when budget allows. Production keeps its box.',
     5, 2, 'new', 'platform', array['self-hosted', 'pulse-cli']::text[], 7),
    ('Move production and staging to a stable server', 'Production, staging, dev, agents and CI share one throttled box, so one heavy job slows every customer.',
     'Every organisation on the central Pulse',
     'Production and staging on their own stable server; dev, AI agents and CI elsewhere (the CI box, Oracle A1). Backups off the box (R2). A written runbook to move again.',
     5, 3, 'new', 'platform', array['self-hosted', 'licences-register']::text[], 8),
    ('Minimal-cost AWS scaling plan', 'There is no plan for when one box is not enough, so scaling will be decided in a hurry and cost too much.',
     'The founder planning growth',
     'The cheapest realistic AWS path in Mumbai (ap-south-1) for later: Lightsail 16 GB or t4g.xlarge with self-run Postgres (about $80 a month all-in), avoiding Fargate, App Runner and RDS at Pulse''s size; with AWS Activate credits. Triggers that say when to move.',
     3, 2, 'new', 'platform', array['self-hosted']::text[], 9),
    ('Separate Pulse company entity', 'Pulse runs on Estate Autopilots'' accounts, so its apps, AI and media services, costs and contracts are mixed with an agency''s.',
     'The founder, investors and Pulse''s customers',
     'Pulse as its own company: its own Play developer account, its own ElevenLabs, Remotion and OpenRouter accounts, its own billing and startup-credit applications, and Estate Autopilots as its founding customer (licence register).',
     4, 3, 'new', 'network', array['licences-register', 'start-own-pulse']::text[], 10),
    ('Business deals between connected companies', 'Connected companies already chat and share tasks in Pulse, but offers, contracts, signatures and compliance still happen over e-mail and paper.',
     'Organisations connected on Pulse (clients, partners, vendors)',
     'Offers and contracts between connected organisations, e-signature, KYC of both sides, and help with GST, CA and CS work (filings, invoices, board resolutions) from vetted professionals inside Pulse.',
     5, 5, 'new', 'network', array['client-connections', 'cross-org-groups', 'referrals', 'billing-documents', 'quote-followups']::text[], 11),
    ('Media Studio', 'Video work is scattered: footage, captures, voice-overs and music live in Drive folders; nobody knows which cut changed what, how often footage was re-shot or why, or how much time each editor spends.',
     'Video teams and agencies (Estate Autopilots'' editors first), and founders making product videos',
     E'Planned · next build.\n• Assets per video: raw footage, screen captures, stills, voice-overs, music and sound effects gathered on the video.\n• Each video tracked from brief → raw capture → edit → review → publish.\n• Editing projects indexed from Premiere Pro, DaVinci Resolve and Final Cut: parse the project, XML and EDL files for sequences, clips, cuts and timestamps, so Pulse knows what changed between versions frame by frame.\n• Change requests pinned to frames and timecodes.\n• Redo tracking: how many times raw footage was re-shot or a cut redone, and why (bad footage, client change round).\n• Editor time and throughput; versions side by side.\n• Works with EA''s video-editor tracking (the Drive md5 and perceptual-hash mapping that already exists in the WhatsApp research tools) and with the Product Story module (a tutorial per version).',
     5, 5, 'planned', 'creative', array['media-review', 'asset-tracker', 'shoot-planning', 'designers-board', 'creative-strategy', 'drive-sync']::text[], 12),
    ('Journey & Social', 'Founders know they should document the journey and post, but the moments pass, nobody writes the post, and agencies do not know what happened inside the company.',
     'Founders documenting their journey (Atlas Crest'' Sales X-Ray and the founder''s own content first)',
     E'Planned · next build.\n• An AI employee (on the organisation''s own server and AI connection) follows the company''s work it is allowed to see: Product Story, releases, tasks and chats.\n• It proposes posts for Instagram, LinkedIn, X and others: captions, carousels, short videos and reels (through the Reels pipeline) and audio.\n• A content calendar; ideation in chat ("what should we post this week?").\n• Prompts at the right moment: "take photos of the setup", "film the two-phone testing".\n• Drafts go through ask-first approval before anything is published.\n• Cheap routing through OpenRouter (Jev router, decision models) with escalation to the Claude subscription.\n• First users: Atlas Crest'' Sales X-Ray documentation and the founder''s own founder content.',
     5, 4, 'planned', 'creative', array['ai-employees', 'ai-ask-first', 'connect-ai', 'agent-workspaces', 'xray-calls-leads']::text[], 13)
  ) as x(title, problem, for_whom, details, impact, effort, status, area, keys, n)
  where not exists (select 1 from pulse.hq_idea i where i.org_id = v_org and lower(i.title) = lower(x.title));

  -- Stack Intelligence: the research of 23 Oct 2026 (upserted by name) and its four budget stacks.
  insert into pulse.stack_tool as t (org_id, name, category, use_case, plan, cost_usd, cost_inr, free_tier, limits, pros, cons, best_for, verdict, verdict_note, status, sources, sort, owner_id, created_by)
  select v_org, x.name, x.category, x.use_case, x.plan, x.cost_usd, x.cost_inr, x.free_tier, x.limits, x.pros, x.cons, x.best_for, x.verdict, x.verdict_note, x.status, x.sources, x.sort, v_person, v_person from (values
  ('Hostinger KVM 4 (current box)', 'compute', 'Production + staging (light, latency-sensitive) — not CI/agents', 'KVM 4: 4 shared vCPU, 16 GB RAM, 200 GB NVMe, 16 TB bw', 25.25, 2399.0, '', 'CPU-credit system (published 2026-10-01): baseline 60% of allocated CPU; full credit balance (17,280 core-seconds) lasts ~3 h at 100%; when depleted the KVM 4 is capped at 30% (≈1.2 cores) until balance recovers to 20%. Older policy: >180 min sustained high CPU => capacity cut 25%/h. Promo ₹1,099/mo, renews ₹2,399/mo for 2 years, paid upfront.', 'Already paid and running
16 GB RAM cheap per GB
Fine for bursty web/API traffic', 'Sustained builds/tests/agents burn credits and get throttled to 30%
No dedicated-CPU tier
Benchmarked steal avg 3.4%, max 9% (Feb 2026)', 'Prod + staging only', 'adopt', 'KEEP for production; evict CI, AI agents and dev builds to another box.', 'adopted', '[{"url": "https://www.hostinger.com/support/?p=19381", "checked": "2026-10-23"}, {"url": "https://www.hostinger.com/support/?p=715", "checked": "2026-10-23"}, {"url": "https://www.hostinger.com/in/vps-hosting", "checked": "2026-10-23"}, {"url": "https://www.vpsbenchmarks.com/trials/hostinger_performance_trial_27Feb2026/endurance_runs", "checked": "2026-10-23"}]'::jsonb, 0),
  ('Hostinger KVM 8 / second KVM 4', 'compute', 'Extra capacity on same provider', 'KVM 8: 8 shared vCPU, 32 GB, 400 GB NVMe', 46.31, 4399.0, '', 'Same credit throttle: drops to 30% when credits run out. Promo ₹2,199/mo then ₹4,399/mo renewal. Second KVM 4 = ₹1,099 promo / ₹2,399 renewal.', 'Same panel/billing
Lots of RAM', 'Same throttling that hurts CI today
Upfront multi-year payment', 'Not recommended for CI/agents', 'hold', 'AVOID for build/agent workloads; a second KVM 4 only makes sense as a prod/staging split.', 'evaluating', '[{"url": "https://www.hostinger.com/in/vps-hosting", "checked": "2026-10-23"}, {"url": "https://www.hostinger.com/support/?p=19381", "checked": "2026-10-23"}]'::jsonb, 1),
  ('Oracle Cloud Always Free (Ampere A1)', 'compute', 'Free ARM box for CI runner, AI agents, dev, Uptime Kuma', 'Always Free: VM.Standard.A1.Flex 2 OCPU / 12 GB (cut from 4/24 on 2026-06-15) + 2x E2.1.Micro + 200 GB block + 10 TB egress', 0.0, 0.0, '1,500 OCPU-hours + 9,000 GB-hours/month A1 (=2 OCPU/12 GB), 200 GB block volume total, 10 TB/month outbound', 'Card required at signup. Must be in HOME region (chosen once, permanent). ''Out of host capacity'' common; user reports for ap-hyderabad-1. Idle reclaim if over 7 days p95 CPU <20% AND network <20% AND memory <20% (A1). Allowance silently halved June 2026; PAYG accounts reportedly keep 4/24 (support emails, unconfirmed).', 'Free, real ARM cores
