  ('Google Cloud free tier', 'compute', 'Trial credits; Cloud Run; TTS', '$300 / 90 days trial; Always Free e2-micro (US regions only), Cloud Run 2M req/month', 0.0, 0.0, '1 e2-micro in us-west1/us-central1/us-east1, 30 GB disk, 1 GB egress; Cloud Run 2M requests, 180k vCPU-s', 'Card/payment method required; India needs INR billing account. Free VM only in US (~250 ms from India).', 'Useful for Chirp 3 HD TTS + Firebase', 'Free VM useless for India latency/CI', 'Billing account for TTS/Firebase only', 'assess', 'Use only as TTS/Firebase billing account.', 'evaluating', '[{"url": "https://docs.cloud.google.com/free/docs/free-cloud-features", "checked": "2026-10-23"}, {"url": "https://cloud.google.com/free", "checked": "2026-10-23"}]'::jsonb, 11),
  ('Azure free account', 'compute', 'Trial credits; Speech F0', '$200 credit for 30 days; 12 months of 750 h each B1s, B2pts v2 (ARM), B2ats v2', 0.0, 0.0, '750 h/month small burstable VMs for 12 months; Azure Speech F0 0.5M neural chars/month', 'Card authorization at signup; must move to PAYG to keep free services after 30 days.', 'Speech F0 has hi-IN and mr-IN voices', 'Free VMs (1 GB RAM) too small for CI', 'Azure Speech free TTS', 'assess', 'Use only for Speech F0 if needed.', 'evaluating', '[{"url": "https://azure.microsoft.com/en-in/free/", "checked": "2026-10-23"}, {"url": "https://azure.microsoft.com/en-in/pricing/details/speech/", "checked": "2026-10-23"}]'::jsonb, 12),
  ('GitHub Actions self-hosted runners', 'ci', 'Run CI on own boxes (Netcup/Oracle) while keeping GitHub workflows', 'Free/Pro/Team; self-hosted minutes free', 0.0, 0.0, 'Self-hosted runner usage is free (docs). Hosted: Free 2,000 min/mo private; Pro/Team 3,000. Hosted Linux 2-core $0.006/min, arm64 $0.005/min.', 'The $0.002/min self-hosted platform fee announced for 2026-03-01 was POSTPONED (no new date). A billing LOCK on the account blocks hosted AND self-hosted jobs (community reports) — must be cleared via Billing / GitHub Support.', 'Zero cost
